import{G as e,W as t,n,rt as r}from"./chunks/framework.DpaCCLuo.js";var i=JSON.parse(`{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}`),a={name:`faq.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to “FAQ”">​</a></h1><h2 id="インストールボタンが押せない" tabindex="-1">インストールボタンが押せない <a class="header-anchor" href="#インストールボタンが押せない" aria-label="Permalink to “インストールボタンが押せない”">​</a></h2><p>Hierarchyでシーンに置いたムルルを選択するか、「対象アバター」にドラッグしてください。Playモード中は操作できません。</p><h2 id="ムルルのアバターがピンクになっている" tabindex="-1">ムルルのアバターがピンクになっている <a class="header-anchor" href="#ムルルのアバターがピンクになっている" aria-label="Permalink to “ムルルのアバターがピンクになっている”">​</a></h2><p>プロジェクトにlilToonを追加してください。lilToonはVCCに最初から入っていないため、別に追加する必要があります。</p><p>lilToonの追加方法は<a href="https://lilxyzw.github.io/lilToon/ja_JP/first.html" target="_blank" rel="noreferrer">公式ドキュメントの「導入手順と簡易的な使い方」</a>にあります。</p><h2 id="unityでリップシンク用の口が表示されない" tabindex="-1">Unityでリップシンク用の口が表示されない <a class="header-anchor" href="#unityでリップシンク用の口が表示されない" aria-label="Permalink to “Unityでリップシンク用の口が表示されない”">​</a></h2><p>Unityの編集画面では、常に元の表情の口が表示されます。リップシンク用の口は、VRChatで話している間だけ表示されます。言葉の切れ目で口がちらつかないよう、声が途切れてから約0.2秒は表示したままにします。</p><p>Unity上でリップシンク用の口を確認したいときは、BlendShapeの値を次のように変えてください。</p><table tabindex="0"><thead><tr><th>オブジェクト</th><th>BlendShape</th><th>値</th></tr></thead><tbody><tr><td>Body</td><td><code>mouth_off</code></td><td>100</td></tr><tr><td>MururuBlinkLipSync &gt; LipSync_Mouth</td><td><code>SE_hide_self</code></td><td>0</td></tr><tr><td>MururuBlinkLipSync &gt; LipSync_Mouth</td><td><code>SE_mouth_A</code>・<code>SE_mouth_I</code>・<code>SE_mouth_U</code>・<code>SE_mouth_E</code>・<code>SE_mouth_O</code></td><td>合計が100以下になるように調整</td></tr></tbody></table><p>確認が終わったら、<code>mouth_off</code> を0、<code>SE_hide_self</code> を100、AIUEOのBlendShapeを0に戻してください。</p><h2 id="リップシンク用の口の見た目が顔と違う" tabindex="-1">リップシンク用の口の見た目が顔と違う <a class="header-anchor" href="#リップシンク用の口の見た目が顔と違う" aria-label="Permalink to “リップシンク用の口の見た目が顔と違う”">​</a></h2><p>リップシンク用の口は、アップロード時にBodyのマテリアルやライティングの設定に自動で合わせます。Bodyのマテリアルを差し替えても、インストールし直す必要はありません。ただし、メニューやアニメーションで切り替えるマテリアルには追従しません。</p><h2 id="vrchatでリップシンクしない" tabindex="-1">VRChatでリップシンクしない <a class="header-anchor" href="#vrchatでリップシンクしない" aria-label="Permalink to “VRChatでリップシンクしない”">​</a></h2><p>マイクがミュートになっていないか、リップシンクを止める表情（LipSync のチェックを外した表情）になっていないか確認してください。</p><h2 id="「標準のmururuと異なる可能性があります」と表示される" tabindex="-1">「標準のMururuと異なる可能性があります」と表示される <a class="header-anchor" href="#「標準のmururuと異なる可能性があります」と表示される" aria-label="Permalink to “「標準のMururuと異なる可能性があります」と表示される”">​</a></h2><p>別体型のムルルや、頭部・口周辺を改変したBody、FBXのScale設定を変更したBodyで表示されます。続行すると、VRChatで話したときに口がずれて表示されることがあります。問題があれば <strong>アンインストール</strong> で元に戻せます。</p><h2 id="「mouth-aから対応するaiueo口頂点を特定できませんでした」と表示される" tabindex="-1">「mouth_Aから対応するAIUEO口頂点を特定できませんでした」と表示される <a class="header-anchor" href="#「mouth-aから対応するaiueo口頂点を特定できませんでした」と表示される" aria-label="Permalink to “「mouth_Aから対応するAIUEO口頂点を特定できませんでした」と表示される”">​</a></h2><p>Bodyの口周辺のメッシュや <code>mouth_A</code> を改変していると導入できません。改変前のBodyで試してください。</p><h2 id="「bodyの親がavatar-rootか確認してください」と表示される" tabindex="-1">「Bodyの親がAvatar Rootか確認してください」と表示される <a class="header-anchor" href="#「bodyの親がavatar-rootか確認してください」と表示される" aria-label="Permalink to “「Bodyの親がAvatar Rootか確認してください」と表示される”">​</a></h2><p>BodyをアバターのRoot直下に置いてください。</p><h2 id="「facial-exパラメータがexpression-parametersとma-parametersに見つかりません」と表示される" tabindex="-1">「Facial EXパラメータがExpression ParametersとMA Parametersに見つかりません」と表示される <a class="header-anchor" href="#「facial-exパラメータがexpression-parametersとma-parametersに見つかりません」と表示される" aria-label="Permalink to “「Facial EXパラメータがExpression ParametersとMA Parametersに見つかりません」と表示される”">​</a></h2><p>MA Menu Itemなどで作られるパラメータの場合は、そのまま続行できます。名前が間違っている場合は、<a href="./settings#詳細設定">詳細設定</a> でパラメータ名を確認してください。</p>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};